import numpy as np
from qiskit.quantum_info import Operator
from qiskit.circuit.library import (
    IGate, XGate, YGate, ZGate, HGate, SGate, SdgGate, TGate, TdgGate, SXGate, SXdgGate,
)

FIXED_GATES = [IGate, XGate, YGate, ZGate, HGate, SGate, SdgGate, TGate, TdgGate, SXGate, SXdgGate]


def get_qiskit_gate(matrix):
    """Return the name of the standard fixed-parameter Qiskit gate matching `matrix`
    (up to global phase), or None if there is no match."""
    target = Operator(np.array(matrix, dtype=complex))
    for gate_class in FIXED_GATES:
        if Operator.equiv(target, Operator(gate_class())):
            return gate_class.__name__
    return None


if __name__ == "__main__":
    unitary = [[0, 1], [1, 0]]
    print(get_qiskit_gate(unitary))  # expected "XGate"

